using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Kits/KIT_README.md", ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Kits", ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        result.Log("Forced import on Kits/KIT_README.md and Kits/ folder");
        result.Log("Kits meta exists: " + System.IO.File.Exists("Assets/Resources/HUDTree/Kits.meta"));
        result.Log("KIT_README.md meta exists: " + System.IO.File.Exists("Assets/Resources/HUDTree/Kits/KIT_README.md.meta"));
    }
}
